package com.kishar.app;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.view.*;import android.widget.*;import android.security.keystore.*;import android.util.Base64;
import java.util.*;import java.security.*;import javax.crypto.*;import javax.crypto.spec.*;import okhttp3.*;import org.json.*;
public class MainActivity extends Activity{
 final int OLIVE=Color.rgb(105,132,67),INK=Color.rgb(25,28,24),BG=Color.rgb(248,249,246),RED=Color.rgb(175,55,45);
 LinearLayout body;TextView statusView;OkHttpClient http;WebSocket socket;Timer hb;boolean connected=false,simulation=true;long seq=0;String server="",robot="",token="",pin="",policy="STOP",home="";
 int d(int n){return(int)(n*getResources().getDisplayMetrics().density+.5f);}
 TextView tx(String s,int z,int c){TextView v=new TextView(this);v.setText(s);v.setTextSize(z);v.setTextColor(c);v.setPadding(d(14),d(10),d(14),d(10));return v;}
 Button bt(String s){Button b=new Button(this);b.setText(s);b.setTextSize(16);b.setTextColor(INK);b.setAllCaps(false);b.setMinHeight(d(50));return b;}
 void add(View v){body.addView(v,new LinearLayout.LayoutParams(-1,-2));} JSONObject jo(){return new JSONObject();} void put(JSONObject o,String k,Object v){try{o.put(k,v);}catch(Exception e){}}
 void title(String s){TextView v=tx(s,25,INK);v.setTypeface(null,1);add(v);}
 String keyAlias(){return "kishar_config_v1";}
 SecretKey cryptoKey()throws Exception{KeyStore ks=KeyStore.getInstance("AndroidKeyStore");ks.load(null);if(!ks.containsAlias(keyAlias())){KeyGenerator g=KeyGenerator.getInstance(KeyProperties.KEY_ALGORITHM_AES,"AndroidKeyStore");g.init(new KeyGenParameterSpec.Builder(keyAlias(),KeyProperties.PURPOSE_ENCRYPT|KeyProperties.PURPOSE_DECRYPT).setBlockModes(KeyProperties.BLOCK_MODE_GCM).setEncryptionPaddings(KeyProperties.ENCRYPTION_PADDING_NONE).build());g.generateKey();}return((KeyStore.SecretKeyEntry)ks.getEntry(keyAlias(),null)).getSecretKey();}
 String protect(String s)throws Exception{byte[] iv=new byte[12];new SecureRandom().nextBytes(iv);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.ENCRYPT_MODE,cryptoKey(),new GCMParameterSpec(128,iv));return Base64.encodeToString(iv,2)+":"+Base64.encodeToString(c.doFinal(s.getBytes("UTF-8")),2);}
 String reveal(String s)throws Exception{String[] p=s.split(":",2);Cipher c=Cipher.getInstance("AES/GCM/NoPadding");c.init(Cipher.DECRYPT_MODE,cryptoKey(),new GCMParameterSpec(128,Base64.decode(p[0],2)));return new String(c.doFinal(Base64.decode(p[1],2)),"UTF-8");}
 void load(){try{SharedPreferences p=getSharedPreferences("kishar_secure",0);server=reveal(p.getString("server",""));robot=reveal(p.getString("robot",""));token=reveal(p.getString("token",""));pin=reveal(p.getString("pin",""));policy=reveal(p.getString("policy",""));home=reveal(p.getString("home",""));}catch(Exception e){}}
 void save(){try{getSharedPreferences("kishar_secure",0).edit().putString("server",protect(server)).putString("robot",protect(robot)).putString("token",protect(token)).putString("pin",protect(pin)).putString("policy",protect(policy)).putString("home",protect(home)).apply();}catch(Exception e){Toast.makeText(this,"تعذر حفظ الإعدادات الآمنة",1).show();}}
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(BG);load();home();}
 void base(){body=new LinearLayout(this);body.setOrientation(LinearLayout.VERTICAL);body.setPadding(d(16),d(18),d(16),d(16));body.setBackgroundColor(BG);ScrollView s=new ScrollView(this);s.addView(body);setContentView(s);}
 void nav(){LinearLayout n=new LinearLayout(this);n.setGravity(Gravity.CENTER);String[] a={"المحادثة","تحكم يدوي","غرفة العمليات","الروبوتات","الإعدادات"};for(String x:a){Button b=bt(x);b.setOnClickListener(v->{if(x.equals("الإعدادات"))settings();else if(x.equals("تحكم يدوي"))manual();else home();});n.addView(b,new LinearLayout.LayoutParams(0,-2,1));}body.addView(n);}
 void sendIntent(String q){JSONObject p=jo();put(p,"text",q);sendFrame("INTENT",p);} void guardedIntent(String q){String z=q.toLowerCase();boolean risky=z.contains("أقلع")||z.contains("اهبط")||z.contains("تحرك")||z.contains("ارفع")||z.contains("انزل")||z.contains("ارجع")||z.contains("درون")||z.contains("ذراع");if(risky){new AlertDialog.Builder(this).setTitle("تأكيد الأمر").setMessage("هذا الأمر قد يحرّك الروبوت أو الذراع. هل تريد إرساله؟").setNegativeButton("إلغاء",null).setPositiveButton("تأكيد",(d,w)->sendIntent(q)).show();}else sendIntent(q);} void home(){base();title("Kishar 🔥");add(tx(connected?"متصل بالخادم الآمن":"غير متصل — الوضع الآمن",16,connected?OLIVE:RED));statusView=tx("بانتظار تأكيد من الخادم…",15,INK);add(statusView);EditText e=new EditText(this);e.setHint("اكتب أمرًا لـ Joker…");e.setTextSize(18);add(e);Button send=bt("إرسال الأمر");send.setOnClickListener(v->{String q=e.getText().toString().trim();if(!q.isEmpty()){JSONObject p=jo();put(p,"text",q);guardedIntent(q);e.setText("");}});add(send);Button con=bt(connected?"قطع الاتصال":"اتصال آمن");con.setOnClickListener(v->{if(connected)disconnect();else connect(false);});add(con);Button stop=bt("إيقاف طوارئ");stop.setTextColor(RED);stop.setOnClickListener(v->sendFrame("EMERGENCY_STOP",jo()));add(stop);nav();}
 void manual(){base();title("التحكم اليدوي الآمن");add(tx("الحركة تستمر فقط أثناء الضغط. عند رفع الإصبع يُرسل STOP فورًا.",15,OLIVE));Button f=bt("▲ أمام");Button b=bt("▼ خلف");Button l=bt("◀ يسار");Button r=bt("يمين ▶");Button stop=bt("توقف");stop.setTextColor(RED);add(f);add(b);add(l);add(r);add(stop);bindHold(f,"FORWARD");bindHold(b,"BACKWARD");bindHold(l,"LEFT");bindHold(r,"RIGHT");stop.setOnClickListener(x->sendFrame("STOP",jo()));Button em=bt("إيقاف طوارئ");em.setTextColor(RED);em.setOnClickListener(x->sendFrame("EMERGENCY_STOP",jo()));add(em);nav();} void bindHold(Button b,String direction){b.setOnTouchListener((v,e)->{if(e.getAction()==MotionEvent.ACTION_DOWN){JSONObject p=jo();put(p,"direction",direction);put(p,"speed",0.2);sendFrame("MOVE_LINEAR",p);return true;}if(e.getAction()==MotionEvent.ACTION_UP||e.getAction()==MotionEvent.ACTION_CANCEL){sendFrame("STOP",jo());return true;}return true;});} void settings(){base();title("الإعدادات الآمنة");add(tx("في الوضع الحقيقي يُسمح فقط بـ wss:// مع شهادة TLS صحيحة.",15,OLIVE));EditText s=new EditText(this);s.setHint("عنوان الخادم: wss://…");s.setText(server);add(s);EditText r=new EditText(this);r.setHint("Robot ID");r.setText(robot);add(r);EditText t=new EditText(this);t.setHint("مفتاح المصادقة");t.setInputType(129);t.setText(token);add(t);EditText p=new EditText(this);p.setHint("بصمة شهادة TLS اختيارية: sha256/…");p.setText(pin);add(p);EditText pol=new EditText(this);pol.setHint("فقد الاتصال: STOP أو RETURN_HOME أو EMERGENCY_LAND");pol.setText(policy);add(pol);EditText h=new EditText(this);h.setHint("نقطة المقر / Home Point");h.setText(home);add(h);Button saveb=bt("حفظ مشفّر");saveb.setOnClickListener(v->{server=s.getText().toString().trim();robot=r.getText().toString().trim();token=t.getText().toString().trim();pin=p.getText().toString().trim();policy=pol.getText().toString().trim().toUpperCase();home=h.getText().toString().trim();save();Toast.makeText(this,"تم الحفظ داخل Android Keystore",0).show();});add(saveb);Button test=bt("اختبار الاتصال");test.setOnClickListener(v->connect(false));add(test);nav();}
 void connect(boolean sim){simulation=sim;if(!simulation&&!server.startsWith("wss://")){Toast.makeText(this,"الاتصال الحقيقي يتطلب wss://",1).show();return;}try{if(sim){connected=true;home();return;}OkHttpClient.Builder builder=new OkHttpClient.Builder().pingInterval(1,java.util.concurrent.TimeUnit.SECONDS);if(!pin.isEmpty()){String host=HttpUrl.parse(server).host();builder.certificatePinner(new CertificatePinner.Builder().add(host,pin.startsWith("sha256/")?pin:"sha256/"+pin).build());}http=builder.build();Request.Builder rb=new Request.Builder().url(server);if(!token.isEmpty())rb.addHeader("Authorization","Bearer "+token);http.newWebSocket(rb.build(),new WebSocketListener(){public void onOpen(WebSocket w,Response x){socket=w;connected=true;startHeartbeat();JSONObject h=jo();put(h,"robot_id",robot);put(h,"client","android");put(h,"disconnect_policy",policy.isEmpty()?"STOP":policy);put(h,"home_point",home);put(h,"command_expiry_ms",1500);sendFrame("HELLO",h);runOnUiThread(()->home());}public void onMessage(WebSocket w,String m){final String safe=m.length()>500?m.substring(0,500):m;runOnUiThread(()->{if(statusView!=null)statusView.setText("آخر رد من الخادم:\n"+safe);Toast.makeText(MainActivity.this,"وصل رد من الخادم",0).show();});}public void onClosed(WebSocket w,int c,String r){stopHeartbeat();connected=false;runOnUiThread(()->{if(statusView!=null)statusView.setText("انتهت جلسة الخادم — لم يُستأنف التحكم تلقائيًا");});}public void onFailure(WebSocket w,Throwable e,Response x){stopHeartbeat();connected=false;runOnUiThread(()->{if(statusView!=null)statusView.setText("خطأ في الاتصال الآمن — الحركة متوقفة");Toast.makeText(MainActivity.this,"فشل الاتصال الآمن",1).show();});}});}catch(Exception e){Toast.makeText(this,"تعذر بدء TLS",1).show();}}
 void startHeartbeat(){stopHeartbeat();hb=new Timer();hb.scheduleAtFixedRate(new TimerTask(){public void run(){sendFrame("HEARTBEAT",jo());}},0,1000);}
 void stopHeartbeat(){if(hb!=null){hb.cancel();hb=null;}}
 void disconnect(){stopHeartbeat();if(socket!=null)socket.close(1000,"user");connected=false;home();}
 synchronized void sendFrame(String type,JSONObject payload){try{JSONObject o=jo();long now=System.currentTimeMillis();put(o,"type",type);put(o,"message_id",UUID.randomUUID().toString());put(o,"robot_id",robot);put(o,"sequence",++seq);put(o,"timestamp_ms",now);put(o,"expires_at_ms",now+1500);put(o,"payload",payload);if(simulation){Toast.makeText(this,"محاكاة: "+type,0).show();return;}if(socket!=null&&connected)socket.send(o.toString());}catch(Exception e){}}
 @Override protected void onPause(){sendFrame("STOP",jo());super.onPause();}
 @Override protected void onDestroy(){stopHeartbeat();if(socket!=null)socket.close(1000,"destroy");super.onDestroy();}
}
